import{_ as a,a as t}from"./chunks/device-pc-portrait.DB8DRUjA.js";import{_ as s,o,c as i,a2 as r}from"./chunks/framework.Dx-TCpNt.js";const m=JSON.parse('{"title":"On Different Devices","description":"One app, several shapes. KomaYomi reflows instead of hiding features behind a separate mobile build, so the same buttons are always somewhere on screen —…","frontmatter":{"description":"One app, several shapes. KomaYomi reflows instead of hiding features behind a separate mobile build, so the same buttons are always somewhere on screen —…"},"headers":[],"relativePath":"guide/devices.md","filePath":"guide/devices.md","lastUpdated":1794768712000}'),n={name:"guide/devices.md"};function l(h,e,d,p,c,u){return o(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="on-different-devices" tabindex="-1">On Different Devices <a class="header-anchor" href="#on-different-devices" aria-label="Permalink to &quot;On Different Devices&quot;">​</a></h1><p>One app, several shapes. KomaYomi reflows instead of hiding features behind a separate mobile build, so the same buttons are always somewhere on screen — they just move around. This page shows how the main windows rearrange. The two desktop shapes have real captures; the phone and tablet slots are waiting for the responsive pass.</p><h2 id="pc-landscape-—-1440-px" tabindex="-1">PC, landscape — 1440 px <a class="header-anchor" href="#pc-landscape-—-1440-px" aria-label="Permalink to &quot;PC, landscape — 1440 px&quot;">​</a></h2><figure class="shot"><img src="'+a+'" alt="1440 px wide window with the library sidebar, three compare panes and the notes column"><figcaption>1440 px: sidebar on the left, three language panes in the middle, notes column on the right.</figcaption></figure><p>At 1440 px the sidebar (around 240 px), the compare stage and the notes column are all visible at once. The three language panes sit side by side, so a whole exchange fits without scrolling, and the notes column stays open above 1180 px — drag its splitter to widen it, or close it with <strong>Notes</strong> (<code>N</code>).</p><h2 id="pc-portrait-—-900-×-1200" tabindex="-1">PC, portrait — 900 × 1200 <a class="header-anchor" href="#pc-portrait-—-900-×-1200" aria-label="Permalink to &quot;PC, portrait — 900 × 1200&quot;">​</a></h2><figure class="shot"><img src="'+t+'" alt="900 by 1200 narrow desktop window with the library collapsed into a drawer and the compare panes stacked"><figcaption>900 × 1200: sidebar folded into a drawer, one compare column, notes closed until you ask for them.</figcaption></figure><p>At 900 px the layout switches to its narrow mode: the library folds into a drawer behind the ☰ button, the compare panes stack in a single column, and the notes column starts closed — <strong>Notes</strong> brings it back. Toolbar groups drop their text labels, and the actions that no longer fit move under <strong>More</strong>.</p><h2 id="phone-portrait-—-390-×-844" tabindex="-1">Phone, portrait — 390 × 844 <a class="header-anchor" href="#phone-portrait-—-390-×-844" aria-label="Permalink to &quot;Phone, portrait — 390 × 844&quot;">​</a></h2><figure class="shot"><div class="shot-missing"><strong>Screenshot pending: phone portrait (390 × 844)</strong> A real capture at this width will land here once the responsive pass is finished. </div><figcaption>Planned screenshot: 390 × 844.</figcaption></figure><h2 id="tablet-portrait-—-820-×-1180" tabindex="-1">Tablet, portrait — 820 × 1180 <a class="header-anchor" href="#tablet-portrait-—-820-×-1180" aria-label="Permalink to &quot;Tablet, portrait — 820 × 1180&quot;">​</a></h2><figure class="shot"><div class="shot-missing"><strong>Screenshot pending: tablet portrait (820 × 1180)</strong> A real capture at this width will land here once the responsive pass is finished. </div><figcaption>Planned screenshot: 820 × 1180.</figcaption></figure><h2 id="tablet-landscape-—-1180-×-820" tabindex="-1">Tablet, landscape — 1180 × 820 <a class="header-anchor" href="#tablet-landscape-—-1180-×-820" aria-label="Permalink to &quot;Tablet, landscape — 1180 × 820&quot;">​</a></h2><figure class="shot"><div class="shot-missing"><strong>Screenshot pending: tablet landscape (1180 × 820)</strong> A real capture at this width will land here once the responsive pass is finished. </div><figcaption>Planned screenshot: 1180 × 820.</figcaption></figure><div class="tip custom-block"><p class="custom-block-title">Capturing your own layouts</p><p>Resize the browser window rather than zooming the page: the breakpoints follow the viewport width, and the notes column and sidebar only change places when the window itself crosses them.</p></div>',15)])])}const b=s(n,[["render",l]]);export{m as __pageData,b as default};
